BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS app;
CREATE TABLE public.tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE,name text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.schools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),code text NOT NULL,name text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,code));
CREATE TABLE public.users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_subject text NOT NULL UNIQUE,email text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),school_id uuid,user_id uuid NOT NULL REFERENCES public.users(id),role_code text NOT NULL CHECK(role_code IN ('foundation_admin','foundation_analyst','principal','school_admin','teacher','guardian','finance_officer')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','revoked')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,school_id) REFERENCES public.schools(tenant_id,id),CHECK ((role_code IN ('foundation_admin','foundation_analyst') AND school_id IS NULL) OR (role_code NOT IN ('foundation_admin','foundation_analyst') AND school_id IS NOT NULL)));
CREATE UNIQUE INDEX memberships_tenant_role_active ON public.memberships(tenant_id,user_id,role_code) WHERE school_id IS NULL AND status='active';
CREATE UNIQUE INDEX memberships_school_role_active ON public.memberships(tenant_id,school_id,user_id,role_code) WHERE school_id IS NOT NULL AND status='active';
CREATE TABLE public.students (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,local_student_no text NOT NULL,display_name text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),FOREIGN KEY(tenant_id,school_id) REFERENCES public.schools(tenant_id,id),UNIQUE(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,local_student_no));
CREATE TABLE public.tenant_policy_configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),version integer NOT NULL CHECK(version>0),status text NOT NULL CHECK(status IN ('draft','active','retired')),max_grant_hours integer NOT NULL DEFAULT 72 CHECK(max_grant_hours BETWEEN 1 AND 72),minimum_aggregate_group integer NOT NULL DEFAULT 10 CHECK(minimum_aggregate_group>=10),export_mode text NOT NULL DEFAULT 'disabled' CHECK(export_mode IN ('disabled','approval_required')),escalation_mode text NOT NULL DEFAULT 'manual_hold' CHECK(escalation_mode IN ('manual_hold','designated_independent')),effective_from timestamptz NOT NULL DEFAULT now(),approved_by uuid REFERENCES public.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,version));
CREATE UNIQUE INDEX tenant_policy_one_active ON public.tenant_policy_configs(tenant_id) WHERE status='active';
CREATE TABLE public.access_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,student_id uuid NOT NULL,requester_user_id uuid NOT NULL REFERENCES public.users(id),grantee_user_id uuid NOT NULL REFERENCES public.users(id),purpose_code text NOT NULL,reason text NOT NULL CHECK(length(trim(reason))>0),requested_resource_types text[] NOT NULL CHECK(cardinality(requested_resource_types)>0),requested_duration_minutes integer NOT NULL CHECK(requested_duration_minutes BETWEEN 1 AND 4320),status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','under_review','conflict_escalated','approved','rejected','revoked')),conflict_flag boolean NOT NULL DEFAULT false,decided_by uuid REFERENCES public.users(id),decision_reason text,created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,FOREIGN KEY(tenant_id,school_id,student_id) REFERENCES public.students(tenant_id,school_id,id),UNIQUE(id,tenant_id,school_id,student_id));
CREATE TABLE public.access_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL UNIQUE,tenant_id uuid NOT NULL,school_id uuid NOT NULL,student_id uuid NOT NULL,grantee_user_id uuid NOT NULL REFERENCES public.users(id),approved_by uuid NOT NULL REFERENCES public.users(id),resource_types text[] NOT NULL CHECK(cardinality(resource_types)>0),starts_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(request_id,tenant_id,school_id,student_id) REFERENCES public.access_requests(id,tenant_id,school_id,student_id),CHECK(expires_at>starts_at AND expires_at<=starts_at + interval '72 hours'));
CREATE TABLE public.approval_escalations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL UNIQUE REFERENCES public.access_requests(id),reason text NOT NULL,status text NOT NULL DEFAULT 'pending_independent_review' CHECK(status IN ('pending_independent_review','rejected','resolved')),independent_reviewer uuid REFERENCES public.users(id),resolution_ref text,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE public.access_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),school_id uuid,actor_user_id uuid REFERENCES public.users(id),request_id uuid REFERENCES public.access_requests(id),grant_id uuid REFERENCES public.access_grants(id),event_type text NOT NULL,result text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),correlation_id text,FOREIGN KEY(tenant_id,school_id) REFERENCES public.schools(tenant_id,id));
CREATE INDEX access_events_tenant_time ON public.access_events(tenant_id,occurred_at DESC);
CREATE INDEX grants_lookup ON public.access_grants(tenant_id,school_id,student_id,grantee_user_id,expires_at);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['tenants','schools','users','memberships','students','tenant_policy_configs','access_requests','access_grants','approval_escalations','access_events'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t); END LOOP; END $$;
COMMIT;
